import {geographicLabels} from './geography.js';
import {matchesText} from './search.js';
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normal=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const labels={all:['Todos los grupos','All groups'],mammal:['Mamíferos','Mammals'],bird:['Aves','Birds'],reptile:['Reptiles','Reptiles'],amphibian:['Anfibios','Amphibians'],invertebrate:['Invertebrados','Invertebrates'],plant:['Plantas','Plants'],fungus:['Hongos','Fungi'],lichen:['Líquenes','Lichens']};
const groupIcon=g=>/bird|aves/.test(g)?'bird':/plant|flora|vascular|bryo/.test(g)?'leaf':/fung|lichen/.test(g)?'sprout':/invertebr|insect/.test(g)?'bug':/fish|peces/.test(g)?'fish':'paw-print';

export class NatureAlbum{
  constructor(context){
    Object.assign(this,context);this.scope='local';this.mode='gallery';this.region='';this.inView=false;this.query='';this.group='all';this.habitat='';this.photos=false;this.page=0;this.size=24;this.chunks=new Map();
    document.querySelector('#modal-content').addEventListener('click',e=>{
      const el=e.target.closest('[data-album]');if(!el)return;
      const action=el.dataset.album;
      if(action==='mode'){this.mode=el.dataset.value;this.paintResults();}
      if(action==='map'&&this.scope==='geography'){this.onNaturalMap({query:this.query,region:this.region,inView:this.inView,naturalType:this.group});return;}
      if(action==='map'){this.onMap({query:this.query,habitat:this.habitat,region:this.region,inView:this.inView,lifeGroup:this.scope==='local'&&this.group!=='all'?this.group:'',category:this.scope==='routes'?'routes':'all'});}
      if(action==='scope'){this.scope=el.dataset.value;this.group='all';this.page=0;this.share();this.open();}
      if(action==='page'){this.page+=Number(el.dataset.value);this.paintResults();document.querySelector('.album-scroll')?.scrollTo({top:0,behavior:'instant'});document.querySelector('.album-result-title')?.focus({preventScroll:true});}
      if(action==='taxon')void this.taxon(el.dataset.id,Number(el.dataset.chunk));
      if(action==='back')this.open();
      if(action==='save-taxon'&&this.activeTaxon){this.onSaveTaxon?.(this.activeTaxon,this.activeChunk);const saved=this.isTaxonSaved(this.activeTaxon.id);el.setAttribute('aria-pressed',String(saved));el.innerHTML=this.icon('bookmark')+this.t(saved?'Guardado':'Guardar especie',saved?'Saved':'Save taxon');window.lucide?.createIcons();}
      if(action==='reset'){this.query='';this.group='all';this.habitat='';this.region='';this.inView=false;this.photos=false;this.page=0;this.onResetFilters?.();this.share();this.open();}
    });
    document.querySelector('#modal-content').addEventListener('input',e=>{
      if(e.target.id!=='album-search')return;this.query=e.target.value;this.page=0;clearTimeout(this.searchTimer);this.searchTimer=setTimeout(()=>{this.share();this.paintResults();},130);
    });
    document.querySelector('#modal-content').addEventListener('change',async e=>{
      if(e.target.id==='album-group')this.group=e.target.value;
      else if(e.target.id==='album-region')this.region=e.target.value;
      else if(e.target.id==='album-inview'){this.inView=e.target.checked;if(this.inView&&this.ensureMap){this.inView=Boolean(await this.ensureMap());const input=document.querySelector('#album-inview');if(input)input.checked=this.inView;}}
      else if(e.target.id==='album-habitat')this.habitat=e.target.value;
      else if(e.target.id==='album-photos')this.photos=e.target.checked;
      else return;
      this.page=0;this.share();this.paintResults();
    });
  }
  useFilters(filters){Object.assign(this,filters);this.page=0;}
  share(){if(this.scope==='geography'){this.onFilters?.({query:this.query,region:this.region,inView:this.inView,naturalType:this.group});return;}if(this.scope!=='national')this.onFilters?.({query:this.query,region:this.region,habitat:this.habitat,inView:this.inView,lifeGroup:this.scope==='local'&&this.group!=='all'?this.group:''});}
  get es(){return this.language()==='es';}
  t(a,b){return this.es?a:b;}
  n(x){return Number(x).toLocaleString(this.es?'es-ES':'en-GB');}
  groupName(g){const fromIndex=this.index?.groups?.find?.(x=>x.id===g||x.group===g);return geographicLabels[g]?.[this.es?0:1]||fromIndex?.label?.[this.language()]||labels[g]?.[this.es?0:1]||g;}
  async load(){
    if(this.index)return;
    if(!this.loading)this.loading=fetch('data/biodiversity/index.json').then(r=>{if(!r.ok)throw Error('index');return r.json();}).then(index=>{this.index=index;this.searchTexts=index.search.map(r=>normal(r[1]+' '+(r[2]||'')));return index;}).catch(()=>{this.error=true;});
    await this.loading;
  }
  open(){
    const es=this.es,catalogue=this.catalogue;
    const geo=this.scope==='geography';const groups=geo?Object.keys(geographicLabels):this.scope!=='national'?[...new Set(catalogue.species.map(s=>s.group))]:[...new Set((this.index?.search||[]).map(r=>r[3]))];
    const habitats=[...new Set(catalogue.places.flatMap(p=>p.habitats))].sort((a,b)=>this.habitatName(a).localeCompare(this.habitatName(b),this.language()));
    const total=this.index?.total_taxa;
    const options=(values,value,fn)=>values.map(g=>`<option value="${escape(g)}" ${g===value?'selected':''}>${escape(fn(g))}</option>`).join('');
    this.showModal('atlas',`<section class="album-shell"><header class="album-header"><div><span class="eyebrow">DR NATURE · ${this.t('CUADERNO DE CAMPO','FIELD NOTES')}</span><h2>${this.t('Atlas natural.','Nature atlas.')}</h2><p>${this.t('Especies, paisajes y rutas, con imágenes y fuentes consultables.','Species, landscapes and trails, with images and accessible sources.')}</p></div><button class="icon-button" data-action="close-modal" aria-label="${this.t('Cerrar atlas','Close atlas')}">${this.icon('x')}</button></header><div class="album-scopes" aria-label="${this.t('Colecciones','Collections')}"><button data-album="scope" data-value="local" aria-pressed="${this.scope==='local'}">${this.t('Vida natural','Natural life')}<span>${catalogue.species.length}</span></button><button data-album="scope" data-value="places" aria-pressed="${this.scope==='places'}">${this.t('Paisajes','Landscapes')}<span>${catalogue.places.length}</span></button><button data-album="scope" data-value="routes" aria-pressed="${this.scope==='routes'}">${this.t('Rutas','Trails')}<span>${catalogue.routes.length}</span></button><button data-album="scope" data-value="geography" aria-pressed="${geo}">${this.t('Agua y espacios','Water and places')}<span>${this.naturalIndex.data?this.n(this.naturalIndex.data.total_features):'IGN'}</span></button><button data-album="scope" data-value="national" aria-pressed="${this.scope==='national'}">${this.t('Inventario de España','Spain inventory')}<span>${total?this.n(total):'MITECO'}</span></button></div><div class="album-layout"><aside class="album-controls"><label class="album-search-label" for="album-search">${this.scope==='local'||this.scope==='national'?this.t('Nombre común o científico','Common or scientific name'):this.t('Nombre del lugar o elemento','Place or feature name')}</label><div class="album-search">${this.icon('search')}<input id="album-search" type="search" value="${escape(this.query)}" placeholder="${geo?this.t('Río, embalse, parque…','River, reservoir, park…'):this.t('Nombre o palabra clave…','Name or keyword…')}"></div>${this.scope!=='national'?`<label for="album-region">${this.t('Zona','Region')}</label><select id="album-region"><option value="">${this.t('Todas las zonas','All regions')}</option>${options(catalogue.regions,this.region,g=>g)}</select><label class="album-check"><input id="album-inview" type="checkbox" ${this.inView?'checked':''}>${this.t('Solo la zona visible del mapa','Only the visible map area')}</label>`:''}${['local','national','geography'].includes(this.scope)?`<label for="album-group">${geo?this.t('Categoría','Category'):this.t('Grupo de vida','Life group')}</label><select id="album-group"><option value="all">${this.t('Todos los grupos','All groups')}</option>${options(groups,this.group,g=>this.groupName(g))}</select>`:''}${!['national','geography'].includes(this.scope)?`<label for="album-habitat">${this.t('Ecosistema','Ecosystem')}</label><select id="album-habitat"><option value="">${this.t('Todos los ecosistemas','All ecosystems')}</option>${options(habitats,this.habitat,g=>this.habitatName(g))}</select><label class="album-check"><input id="album-photos" type="checkbox" ${this.photos?'checked':''}>${this.t('Con fotografía','With a photograph')}</label>`:''}<button class="album-reset" data-album="reset">${this.t('Limpiar filtros','Clear filters')}${this.icon('rotate-ccw')}</button>${geo?`<p class="geography-region-note">${this.t('La zona incluye elementos que intersectan o tocan sus límites oficiales.','The region includes features intersecting or touching its official boundaries.')}</p>`:''}<div class="album-source"><small>${this.t('PROCEDENCIA','PROVENANCE')}</small><p>${geo?this.t('Geometrías de agua IGN y espacios protegidos MITECO. Se consultan por nombre, tipo o área visible.','IGN water geometry and MITECO protected areas. Search by name, type or visible area.'):this.scope!=='national'?this.t('Fichas de los lugares del atlas, con fotografías, rasgos y fuentes.','Entries linked to places in the atlas, with photographs, traits and sources.'):this.t('Lista Patrón del Inventario Español del Patrimonio Natural y de la Biodiversidad. Taxonomía de ámbito nacional.','Reference checklist from Spain’s Natural Heritage and Biodiversity Inventory. National taxonomic coverage.')}</p>${this.scope==='national'?`<a href="https://iepnb.gob.es/" target="_blank" rel="noopener noreferrer">MITECO · IEPNB ${this.icon('external-link')}</a><small>${this.t('La inclusión en España no implica presencia en Madrid.','Inclusion in Spain does not establish presence in Madrid.')}</small>`:''}</div></aside><div class="album-scroll"><div class="album-results-head"><h3 class="album-result-title" tabindex="-1"></h3><span class="album-range"></span></div><div class="album-view-modes">${this.scope!=='national'?`<button data-album="map">${this.icon('map')}${this.t('Mapa','Map')}</button>`:''}<button data-album="mode" data-value="list" aria-pressed="${this.mode==='list'}">${this.icon('list')}${this.t('Lista','List')}</button><button data-album="mode" data-value="gallery" aria-pressed="${this.mode==='gallery'}">${this.icon('layout-grid')}${this.t('Galería','Gallery')}</button></div><div id="album-results"></div><nav class="album-pagination" aria-label="${this.t('Páginas del álbum','Album pages')}"></nav></div></div></section>`);
    this.paintResults();
    if(geo&&!this.naturalIndex.data){void this.naturalIndex.load().then(()=>{if(this.isOpen()&&this.scope==='geography')this.open();});}
    if(this.scope==='national'&&!this.index&&!this.error)void this.load().then(()=>{if(this.isOpen())this.open();});
  }
  entries(){
    const q=normal(this.query);if(this.scope==='geography')return this.naturalIndex.query({query:this.query,type:this.group,region:this.region,bounds:this.inView?this.naturalBounds():null});
    if(this.scope==='places')return this.catalogue.places.filter(p=>this.placeEligible(p)&&matchesText(this.placeName(p)+' '+this.langText(p.summary),this.query)&&(!this.photos||this.imageFile('places',p.id)));
    if(this.scope==='routes')return this.catalogue.routes.filter(r=>this.routeEligible(r)&&(!this.photos||this.imageFile('places',r.place_id)));
    if(this.scope==='national')return (this.index?.search||[]).filter((r,i)=>(this.group==='all'||r[3]===this.group)&&this.searchTexts[i].includes(q));
    const ids=(this.region||this.habitat||this.inView||this.hasRouteFilters?.())?new Set(this.catalogue.places.filter(this.placeEligible).flatMap(p=>p.species_ids)):null;
    return this.catalogue.species.filter(s=>(this.group==='all'||s.group===this.group)&&(!ids||ids.has(s.id))&&(!this.photos||this.imageFile('species',s.id))&&matchesText(this.speciesName(s)+' '+s.scientific_name+' '+s.documented_area+' '+this.catalogue.places.filter(p=>p.species_ids.includes(s.id)).map(p=>this.placeName(p)).join(' '),this.query)).sort((a,b)=>Number(Boolean(this.imageFile('species',b.id)))-Number(Boolean(this.imageFile('species',a.id)))||this.speciesName(a).localeCompare(this.speciesName(b),this.language()));
  }
  paintResults(){
    const host=document.querySelector('#album-results');if(!host)return;
    const entries=this.entries(),pages=Math.max(1,Math.ceil(entries.length/this.size));this.page=Math.min(Math.max(0,this.page),pages-1);
    const start=this.page*this.size,list=entries.slice(start,start+this.size),national=this.scope==='national',geo=this.scope==='geography';
    document.querySelector('.album-result-title').textContent=geo?this.t('Geometrías documentadas','Documented geometry'):this.scope==='places'?this.t('Paisajes y espacios naturales','Landscapes and natural places'):this.scope==='routes'?this.t('Itinerarios documentados','Documented trails'):national?this.t('Referencia nacional','National reference'):this.t('Vida en estos paisajes','Life in these landscapes');
    document.querySelector('.album-range').textContent=entries.length?`${this.n(start+1)}–${this.n(Math.min(start+this.size,entries.length))} / ${this.n(entries.length)}`:this.t('Sin resultados','No results');
    host.className=(national||geo?'taxon-grid':'album-grid')+(this.mode==='list'?' album-list':'');document.querySelectorAll('.album-view-modes [aria-pressed]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.value===this.mode)));
    if(geo&&!this.naturalIndex.data)host.innerHTML=`<p class="album-message" role="status">${this.t('Cargando el índice cartográfico…','Loading the geographic index…')}</p>`;
    else if(national&&!this.index)host.innerHTML=`<p class="album-message" role="status">${this.error?this.t('El inventario no se pudo cargar. Puedes seguir explorando las fichas del territorio.','The inventory could not load. Landscape entries remain available.'):this.t('Cargando la referencia del MITECO…','Loading the MITECO reference…')}</p>`;
    else if(!list.length)host.innerHTML=`<div class="album-message"><h3>${this.t('No hay coincidencias.','No matches.')}</h3><p>${this.t('Prueba otro nombre o amplía los filtros.','Try another name or broaden the filters.')}</p><button class="button" data-album="reset">${this.t('Limpiar filtros','Clear filters')}</button></div>`;
    else host.innerHTML=list.map(s=>geo?`<button class="taxon-card" data-action="natural" data-id="${escape(s[0])}"><span class="taxon-symbol">${this.icon(s[2]==='protected-area'?'trees':'waves')}</span><span><small>${escape(this.groupName(s[2]))}</small><strong>${escape(s[1]||this.t('Sin topónimo en la fuente','Unnamed in the source'))}</strong><em>${s[0].startsWith('ign:')?'IGN · IGR Hidrografía':'MITECO · ENP'}</em></span>${this.icon('arrow-up-right')}</button>`:['places','routes'].includes(this.scope)?this.landscapeCard(s):national?`<button class="taxon-card" data-album="taxon" data-id="${escape(s[0])}" data-chunk="${s[4]}"><span class="taxon-symbol">${this.icon(groupIcon(s[3]))}</span><span><small>${escape(this.groupName(s[3]))}</small><strong>${escape(s[2]||s[1])}</strong><em>${escape(s[1])}</em></span>${this.icon('arrow-up-right')}</button>`:`<button class="album-card ${this.imageFile('species',s.id)?'':'album-card-text'}" data-action="species" data-id="${s.id}">${this.imageFile('species',s.id)?this.photo('species',s.id,this.speciesName(s)):`<div class="album-specimen">${this.icon(groupIcon(s.group))}<span>${this.t('Ficha de campo','Field entry')}</span></div>`}<div class="album-card-copy"><span class="small-label">${escape(this.groupName(s.group))}</span><h3>${escape(this.speciesName(s))}</h3><em>${escape(s.scientific_name)}</em><p>${escape(this.langText(s.summary))}</p><span class="album-card-open">${this.t('Abrir ficha','Open entry')}${this.icon('arrow-up-right')}</span></div></button>`).join('');
    document.querySelector('.album-pagination').innerHTML=`<button class="button" data-album="page" data-value="-1" ${this.page===0?'disabled':''}>${this.icon('arrow-left')}${this.t('Anterior','Previous')}</button><span>${this.page+1} / ${this.n(pages)}</span><button class="button" data-album="page" data-value="1" ${this.page>=pages-1?'disabled':''}>${this.t('Siguiente','Next')}${this.icon('arrow-right')}</button>`;
    window.lucide?.createIcons();
  }
  landscapeCard(item){
    const isRoute=this.scope==='routes',place=isRoute?this.placeOf(item.place_id):item,title=isRoute?this.routeName(item):this.placeName(item),kind=isRoute?'route':'place';
    return `<button class="album-card ${this.imageFile('places',place.id)?'':'album-card-text'}" data-action="${kind}" data-id="${item.id}">${this.imageFile('places',place.id)?this.photo('places',place.id,title):`<div class="album-specimen">${this.icon(isRoute?'route':'mountain')}<span>${this.t('Fotografía pendiente','Photograph pending')}</span></div>`}<div class="album-card-copy"><span class="small-label">${escape(place.regions.join(' · '))}</span><h3>${escape(title)}</h3><em>${isRoute?(item.distance_km?`${item.distance_km} km · `:'')+(item.duration_minutes?`${item.duration_minutes} min`:''):escape(place.habitats.slice(0,3).map(this.habitatName).join(' · '))}</em><p>${escape(this.langText(place.summary))}</p><span class="album-card-open">${this.t('Ver en el mapa','Open on the map')}${this.icon('arrow-up-right')}</span></div></button>`;
  }
  async taxon(id,chunkIndex){
    const chunk=this.index?.chunks?.[chunkIndex];if(!chunk)return;
    this.showModal('taxon',this.header(this.t('Referencia taxonómica','Taxonomic reference'))+`<div class="modal-body" role="status">${this.t('Cargando registro…','Loading record…')}</div>`);
    try{
      if(!this.chunks.has(chunk.file)){const res=await fetch(chunk.file);if(!res.ok)throw Error('chunk');this.chunks.set(chunk.file,await res.json());if(this.chunks.size>6)this.chunks.delete(this.chunks.keys().next().value);}
      const s=this.chunks.get(chunk.file).records.find(r=>String(r.id)===String(id));if(!s)throw Error('record');
      this.activeTaxon=s;this.activeChunk=chunkIndex;
      const known=this.catalogue.species.find(r=>normal(r.scientific_name)===normal(s.scientific_name));
      const tax=[['kingdom','Reino','Kingdom'],['phylum','Filo','Phylum'],['class','Clase','Class'],['order','Orden','Order'],['family','Familia','Family'],['genus','Género','Genus'],['rank','Rango','Rank']].filter(([k])=>s[k]);
      this.showModal('taxon',`<article class="taxon-entry">${this.header(escape(s.common_name||s.scientific_name),escape(s.scientific_name),this.t('LISTA PATRÓN · MITECO','REFERENCE CHECKLIST · MITECO'))}<div class="modal-body"><button class="link-button" data-album="back">${this.icon('arrow-left')}${this.t('Volver al atlas','Back to atlas')}</button><div class="taxon-entry-intro"><span class="taxon-entry-symbol">${this.icon(groupIcon(s.group))}</span><div><h3>${this.t('Identidad y clasificación','Identity and classification')}</h3><p>${this.t('Registro del inventario nacional. Consulta su clasificación y continúa en las fuentes para conocer su distribución y ecología.','National inventory record. Read its classification and continue to the sources for distribution and ecology.')}</p><span class="taxon-scope">${this.t('Ámbito: España','Coverage: Spain')} · ${escape(this.groupName(s.group))}</span></div></div><button class="button" data-album="save-taxon" aria-pressed="${this.isTaxonSaved(s.id)}">${this.icon('bookmark')}${this.isTaxonSaved(s.id)?this.t('Guardado','Saved'):this.t('Guardar especie','Save taxon')}</button><dl class="taxon-classification">${tax.map(([k,es,en])=>`<div><dt>${this.t(es,en)}</dt><dd>${escape(s[k])}</dd></div>`).join('')}</dl>${known?`<button class="button primary" data-action="species" data-id="${known.id}">${this.t('Abrir ficha ilustrada de Dr Nature','Open illustrated Dr Nature entry')}${this.icon('arrow-up-right')}</button>`:''}<div class="taxon-references"><h3>${this.t('Seguir explorando','Explore further')}</h3><a class="route-item" href="${escape(s.source_url)}" target="_blank" rel="noopener noreferrer"><strong>MITECO · IEPNB</strong><span>${this.t('Registro original','Original record')}</span>${this.icon('external-link')}</a><a class="route-item" href="https://${this.es?'es':'en'}.wikipedia.org/w/index.php?search=${encodeURIComponent(s.scientific_name)}" target="_blank" rel="noopener noreferrer"><strong>Wikipedia</strong><span>${this.t('Buscar el nombre científico','Search by scientific name')}</span>${this.icon('external-link')}</a><a class="route-item" href="https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(s.scientific_name)}&title=Special:MediaSearch&type=image" target="_blank" rel="noopener noreferrer"><strong>Wikimedia Commons</strong><span>${this.t('Fotografías y sus licencias','Photographs and their licences')}</span>${this.icon('external-link')}</a></div><p class="taxon-provenance">${this.t('Referencia nacional, no un avistamiento local. Taxonomía y nombres: MITECO / IEPNB · CC BY 4.0.','National reference, not a local sighting. Taxonomy and names: MITECO / IEPNB · CC BY 4.0.')} <a href="data/biodiversity/metadata.json" target="_blank">${this.t('Procedencia de los datos','Data provenance')}</a></p></div></article>`);
    }catch{this.showModal('taxon',this.header(this.t('Registro no disponible','Record unavailable'))+`<div class="modal-body"><button class="button" data-album="back">${this.t('Volver al atlas','Back to atlas')}</button></div>`);}
  }
}
